/**
 * Recipe image mapping.
 *
 * The only place that knows where a recipe photo lives. Images are committed
 * to public/recipes/ and referenced relatively, so they resolve both in the
 * dev server and inside the APK (which serves the build from
 * /assets/www/index.html - see packaging/fireos-android).
 *
 * src/data/recipeImages.json is generated by scripts/fetch-recipe-images.mjs
 * and carries the source URL and credit for every photo.
 */
import manifest from '../data/recipeImages.json' with { type: 'json' }

const images = manifest.images || {}

/**
 * Public URL for a recipe photo, or null when none is shipped.
 * @param {string} recipeId
 * @returns {string|null}
 */
export function imageFor(recipeId) {
  const entry = images[recipeId]
  if (!entry || !entry.file) return null
  return `./recipes/${entry.file}`
}

/**
 * Provenance for a photo (used by the credits screen / docs).
 * @param {string} recipeId
 * @returns {{provider?: string, source?: string, page?: string, credit?: string, license?: string}|null}
 */
export function creditFor(recipeId) {
  const entry = images[recipeId]
  if (!entry) return null
  const { provider, source, page, credit, license } = entry
  return { provider, source, page, credit, license }
}

/** Number of recipes that ship with a photo. */
export function imageCount() {
  return Object.keys(images).length
}

/** Ids that have a photo. */
export function imageIds() {
  return Object.keys(images)
}
